content.solution_code:
class GripperArm {
    constructor() {
        this.holdingItem = false;
    }

    grab(item) {
        if (this.holdingItem) {
            return "Arm is already holding an item.";
        }
        this.holdingItem = true;
        return `Arm grabbed ${item}.`;
    }

    release() {
        if (!this.holdingItem) {
            return "Arm is not holding any item to release.";
        }
        this.holdingItem = false;
        return "Arm released item.";
    }
}

class ScannerSensor {
    constructor() {
        // No specific state for now
    }

    scanArea(range) {
        if (range <= 0 || range > 100) {
            return "Invalid scan range. Must be between 1 and 100.";
        }
        return `Scanned area with range ${range} units.`;
    }
}

class FactoryRobot {
    constructor(id) {
        this.id = id;
        this.arm = new GripperArm();
        this.scanner = new ScannerSensor();
    }

    performGrab(item) {
        return this.arm.grab(item);
    }

    performRelease() {
        return this.arm.release();
    }

    performScan(range) {
        return this.scanner.scanArea(range);
    }
}

